{
  "sentences": [
    {
      "en": "ZIL estimates the camera pose of an image relative to a LiDAR point cloud without needing prior training on the specific scene.",
      "es": "ZIL estima la pose de la cámara de una imagen en relación con una nube de puntos LiDAR sin necesidad de entrenamiento previo en la escena específica.",
      "sources": [0, 2]
    },
    {
      "en": "It uses Vision and Point Transformers to encode images and LiDAR point clouds separately.",
      "es": "Utiliza Vision y Point Transformers para codificar imágenes y nubes de puntos LiDAR por separado.",
      "sources": [3]
    },
    {
      "en": "ZIL improves pose accuracy by predicting 3D coordinates, without requiring extra labeled data.",
      "es": "ZIL mejora la precisión de la pose al predecir coordenadas 3D, sin requerir datos etiquetados adicionales.",
      "sources": [4]
    },
    {
      "en": "Normalizing camera intrinsics and LiDAR vertical-axis origin is necessary for zero-shot generalization.",
      "es": "Normalizar los parámetros de la cámara y el origen del eje vertical LiDAR es necesario para la generalización en modo zero-shot.",
      "sources": [5]
    },
    {
      "en": "Trained on 1.4 million LiDAR frames from seven datasets, ZIL reduces translation and rotation errors by up to 87% and 76% compared to previous methods.",
      "es": "Entrenado con 1.4 millones de fotogramas LiDAR de siete conjuntos de datos, ZIL reduce los errores de traslación y rotación hasta en un 87% y 76% en comparación con métodos anteriores.",
      "sources": [6]
    }
  ]
}

{
  "sentences": [
    {
      "en": "Magnetic symmetry can create spin textures in momentum space without net magnetization, classified by their behavior under momentum reversal.",
      "es": "La simetría magnética puede crear texturas de spin en el espacio de momento sin magnetización neta, clasificadas por su comportamiento bajo inversión de momento.",
      "sources": [0]
    },
    {
      "en": "Odd-parity spin textures have been seen in electronic bands of compensated magnets, but not in collective bosonic excitations like magnons.",
      "es": "Las texturas de spin de paridad impar se han observado en bandas electrónicas de imanes compensados, pero no en excitaciones bosónicas colectivas como los magnones.",
      "sources": [2]
    },
    {
      "en": "Magnons, which carry spin angular momentum in insulating magnets without charge flow, offer a way to study this missing state.",
      "es": "Los magnones, que transportan momento angular de spin en imanes aislantes sin flujo de carga, ofrecen una forma de estudiar este estado ausente.",
      "sources": [3]
    },
    {
      "en": "In BiFeO3, ferroelectric switching reverses the odd-parity magnon spin splitting, confirmed by spin-current measurements and theoretical predictions.",
      "es": "En BiFeO3, el conmutación ferroeléctrica invierte la división de spin de magnones de paridad impar, confirmada por mediciones de corriente de spin y predicciones teóricas.",
      "sources": [5, 6, 8]
    },
    {
      "en": "The programmed magnon spin enables field-free switching of a ferromagnet and demonstrates XNOR logic-in-memory at room temperature.",
      "es": "El spin de magnones programado permite la conmutación sin campo de un ferromagneto y demuestra lógica XNOR dentro de la memoria a temperatura ambiente.",
      "sources": [9, 10]
    }
  ]
}

{
  "sentences": [
    {
      "en": "Recent advances in generative artificial intelligence allow the creation of complex human motion with high detail.",
      "es": "Avances recientes en inteligencia artificial generativa permiten crear movimiento humano complejo con alto detalle.",
      "sources": [0]
    },
    {
      "en": "Current text-to-motion systems ignore non-semantic features of text, treating them as noise.",
      "es": "Los sistemas actuales de texto a movimiento ignoran características no semánticas del texto, tratándolas como ruido.",
      "sources": [1]
    },
    {
      "en": "This work treats those ignored structural features as the main signal to analyze.",
      "es": "Este trabajo trata esas características estructurales ignoradas como la señal principal para analizar.",
      "sources": [2]
    },
    {
      "en": "The method converts dance movements into 256 stylistic regions using Principal Component Analysis and K-Means clustering.",
      "es": "El método convierte los movimientos de danza en 256 regiones estilísticas usando Análisis de Componentes Principales y agrupamiento K-Means.",
      "sources": [4]
    },
    {
      "en": "Text is mapped directly from its raw bytes to these regions, creating a deterministic sequence called the choreographic genome.",
      "es": "El texto se mapea directamente desde sus bytes crudos a estas regiones, creando una secuencia determinista llamada genoma coreográfico.",
      "sources": [5]
    },
    {
      "en": "A precomputed plausibility graph and physics routines turn this sequence into smooth, full-body movement.",
      "es": "Un gráfico de plausibilidad precalculado y rutinas de física convierten esta secuencia en movimiento suave y corporal completo.",
      "sources": [6]
    },
    {
      "en": "Different texts, including Shakespeare, code, and non-ASCII scripts, produce visibly distinct dances.",
      "es": "Textos diferentes, incluyendo Shakespeare, código y scripts no-ASCII, producen danzas visiblemente distintas.",
      "sources": [7]
    },
    {
      "en": "Scripts marginalized by ASCII-centric computing show nearly three times more movement per character.",
      "es": "Los scripts marginados por la computación centrada en ASCII muestran casi tres veces más movimiento por carácter.",
      "sources": [7]
    },
    {
      "en": "This is framed as a critical and poetic visualization, not a motion-synthesis benchmark, questioning what we count as signal.",
      "es": "Esto se presenta como una visualización crítica y poética, no como un benchmark de síntesis de movimiento, cuestionando lo que consideramos señal.",
      "sources": [8]
    }
  ]
}

{
  "sentences": [
    {
      "en": "The authors created ClimTip-GML, a global climate dataset with high resolution, to study the effects of climate tipping events like Amazon rainforest collapse or AMOC slowdown.",
      "es": "Los autores crearon ClimTip-GML, un conjunto de datos climáticos globales con alta resolución, para estudiar los efectos de eventos de inflexión climática como el colapso de la selva amazónica o el frenado de la AMOC.",
      "sources": [1]
    },
    {
      "en": "The dataset includes 100-year simulations under preindustrial, historical, and +2°C warming conditions, with and without tipping events in the AMOC or ARF.",
      "es": "El conjunto de datos incluye simulaciones de 100 años bajo condiciones preindustriales, históricas y con un calentamiento de +2°C, con y sin eventos de inflexión en la AMOC o la ARF.",
      "sources": [2]
    },
    {
      "en": "They used generative machine learning trained on reanalysis data to correct biases and increase resolution while keeping physical consistency across variables.",
      "es": "Usaron aprendizaje automático generativo entrenado con datos de reanálisis para corregir sesgos y aumentar la resolución, manteniendo la coherencia física entre las variables.",
      "sources": [3]
    },
    {
      "en": "Validation showed reduced biases, better small-scale patterns, stronger multivariate correlations, and consistent responses to warming and tipping events.",
      "es": "La validación mostró sesgos reducidos, patrones a pequeña escala mejorados, correlaciones multivariadas más fuertes y respuestas consistentes al calentamiento y los eventos de inflexión.",
      "sources": [4]
    },
    {
      "en": "The dataset enables more accurate assessments of how AMOC and ARF tipping events affect ecosystems and human systems, supporting policy decisions.",
      "es": "El conjunto de datos permite evaluaciones más precisas de cómo los eventos de inflexión de la AMOC y la ARF afectan a los ecosistemas y sistemas humanos, apoyando decisiones de política.",
      "sources": [5]
    }
  ]
}

{
  "sentences": [
    {
      "en": "The authors created a detailed gene expression map of the forebrain in cleaner wrasse fish using single-nucleus profiling.",
      "es": "Los autores crearon un mapa detallado de la expresión génica en el telencéfalo de peces limpiaadores usando perfilado de núcleos individuales.",
      "sources": [2]
    },
    {
      "en": "They analyzed about 67,000 nuclei and found cell types similar to those in mammals, including neurons linked to social behavior and striatal or hippocampal-like cells.",
      "es": "Analizaron aproximadamente 67,000 núcleos y encontraron tipos de células similares a las de mamíferos, incluyendo neuronas vinculadas al comportamiento social y células parecidas a las estriadas o hipocampales.",
      "sources": [3]
    },
    {
      "en": "Fish interacting socially showed changes in radial glial cells and gene networks tied to learning, while observers showed signs of motivation and readiness.",
      "es": "Los peces que interactuaron socialmente mostraron cambios en células radiales gliales y redes génicas vinculadas al aprendizaje, mientras que los observadores mostraron señales de motivación y preparación.",
      "sources": [4]
    },
    {
      "en": "The findings suggest these cellular and molecular features may underlie complex social behavior across vertebrates.",
      "es": "Los hallazgos sugieren que estas características celulares y moleculares podrían subyacer al comportamiento social complejo en vertebrados.",
      "sources": [5]
    }
  ]
}

{
  "sentences": [
    {
      "en": "Autonomous underwater vehicles (AUVs) can collect ocean ecology data without divers, but may disturb fish and reduce their scientific usefulness.",
      "es": "Los vehículos submarinos autónomos (AUV) pueden recopilar datos de la ecología oceánica sin buceadores, pero pueden perturbar a los peces y reducir su utilidad científica.",
      "sources": [0, 1]
    },
    {
      "en": "Researchers tested a conventional thruster-driven AUV, a biomimetic AUV shaped like a sea turtle, and a diver to measure fish behavior changes.",
      "es": "Los investigadores probaron un AUV impulsado por hélices, un AUV biomimético con forma de tortuga marina y un buceador para medir cambios en el comportamiento de los peces.",
      "sources": [2, 3]
    },
    {
      "en": "Both AUVs caused measurable changes in fish behavior, though differences between them were not statistically significant after correction.",
      "es": "Ambos AUV causaron cambios medibles en el comportamiento de los peces, aunque las diferencias entre ellos no fueron estadísticamente significativas tras la corrección.",
      "sources": [5, 6]
    },
    {
      "en": "Fish responses were larger near divers than near AUVs, but this comparison is limited by a small number of diver trials and other uncertainties.",
      "es": "Las respuestas de los peces fueron mayores cerca de los buceadores que cerca de los AUV, pero esta comparación está limitada por un pequeño número de pruebas con buceadores y otras incertidumbres.",
      "sources": [7]
    },
    {
      "en": "The results are preliminary due to experimental limits, but this study offers the first dataset to benchmark how biomimetic robots affect wildlife in natural settings.",
      "es": "Los resultados son preliminares debido a limitaciones experimentales, pero este estudio ofrece el primer conjunto de datos para evaluar cómo los robots biomiméticos afectan a la vida silvestre en entornos naturales.",
      "sources": [8]
    }
  ]
}

{
  "sentences": [
    {
      "en": "The environment is increasingly contaminated with synthetic plastics.",
      "es": "El entorno está cada vez más contaminado con plásticos sintéticos.",
      "sources": [0]
    },
    {
      "en": "Researchers analyzed brain samples to determine if fluorescent particles were plastics.",
      "es": "Los investigadores analizaron muestras cerebrales para determinar si las partículas fluorescentes eran plásticos.",
      "sources": [2, 3]
    },
    {
      "en": "Pyrolysis gas-chromatography/mass spectroscopy detected 10 types of plastics in brain pellets.",
      "es": "La pirolisis cromatografía de gases/espectrometría de masas detectó 10 tipos de plásticos en los pellets cerebrales.",
      "sources": [4]
    },
    {
      "en": "Fluorescent particles matching polyethylene and polypropylene were found on blood vessel walls.",
      "es": "Partículas fluorescentes que coinciden con polietileno y polipropileno se encontraron en las paredes de los vasos sanguíneos.",
      "sources": [7, 11]
    },
    {
      "en": "These findings suggest plastics may be linked to brain blood vessel changes, but causation is not proven.",
      "es": "Estos hallazgos sugieren que los plásticos podrían estar relacionados con cambios en los vasos sanguíneos cerebrales, pero no se prueba causalidad.",
      "sources": [13, 14]
    }
  ]
}

{
  "sentences": [
    {
      "en": "The authors developed a particle-based simulation framework to model how solutes move through a chain of valve-separated lymphatic vessel segments called lymphangions.",
      "es": "Los autores desarrollaron un marco de simulación basado en partículas para modelar cómo se mueven los solutos a través de una cadena de segmentos vasculares separados por válvulas llamados linfangiones.",
      "sources": [3]
    },
    {
      "en": "Their simulations show that solute transport in lymphatic vessels produces bursty concentration patterns over time, matching in vivo observations.",
      "es": "Sus simulaciones muestran que el transporte de solutos en los vasos linfáticos produce patrones de concentración intermitentes con el tiempo, coincidiendo con observaciones in vivo.",
      "sources": [5]
    },
    {
      "en": "They found that valve synchronization, not particle release time, controls when peak solute concentrations occur during each pumping cycle.",
      "es": "Encontraron que la sincronización de las válvulas, no el momento de liberación de las partículas, controla cuándo ocurren las concentraciones máximas de soluto en cada ciclo de bombeo.",
      "sources": [6]
    },
    {
      "en": "Diffusivity and receiver placement were shown to affect how sharp these concentration peaks are.",
      "es": "La difusividad y la ubicación del receptor afectan lo nítidas que son estas picos de concentración.",
      "sources": [6]
    },
    {
      "en": "The framework offers a first quantitative basis for modeling solute transport in the lymphatic system and supports potential molecular communication applications.",
      "es": "El marco ofrece una base cuantitativa inicial para modelar el transporte de solutos en el sistema linfático y apoya posibles aplicaciones de comunicación molecular.",
      "sources": [7]
    }
  ]
}

{
  "sentences": [
    {
      "en": "In many European water polo leagues, relegation matters more than winning the championship.",
      "es": "En muchas ligas europeas de waterpolo, el descenso importa más que ganar el campeonato.",
      "sources": [0]
    },
    {
      "en": "The study focuses on predicting relegation using a new Bayesian model that breaks scoring into even-strength, man-up, and penalty components.",
      "es": "El estudio se centra en predecir el descenso usando un nuevo modelo bayesiano que divide la anotación en componentes de juego normal, superioridad numérica y penales.",
      "sources": [1, 4]
    },
    {
      "en": "The model shows that these scoring components are not independent because they share a limited number of possessions.",
      "es": "El modelo muestra que estos componentes de anotación no son independientes porque comparten un número limitado de posesiones.",
      "sources": [5]
    },
    {
      "en": "Using data from 940 matches, the model identifies the relegated club before the league table does and predicts the play-out teams better than the table.",
      "es": "Usando datos de 940 partidos, el modelo identifica al club relegado antes que la tabla de posiciones y predice mejor los equipos del play-out que la tabla.",
      "sources": [6]
    },
    {
      "en": "Promoted clubs start weaker in all scoring areas except drawing exclusions, and knowing they were promoted helps forecasts, but knowing how they were promoted does not.",
      "es": "Los clubes promovidos comienzan más débiles en todas las áreas de anotación excepto en la obtención de exclusiones, y saber que fueron promovidos ayuda a las predicciones, pero saber cómo fueron promovidos no.",
      "sources": [3, 7]
    }
  ]
}

{
  "sentences": [
    {
      "en": "Researchers activated oxytocin neurons in macaques using a chemogenetic method to study social behavior.",
      "es": "Los investigadores activaron neuronas de oxitocina en macacos usando un método quimigénico para estudiar el comportamiento social.",
      "sources": [2]
    },
    {
      "en": "They used a non-invasive method called digit-tracking to measure how monkeys explored face images with their fingers.",
      "es": "Usaron un método no invasivo llamado seguimiento digital para medir cómo los monos exploraban imágenes de caras con los dedos.",
      "sources": [3]
    },
    {
      "en": "Activating these neurons made the monkeys look more at the eyes and less at other parts of the face.",
      "es": "Activar estas neuronas hizo que los monos miraran más los ojos y menos otras partes de la cara.",
      "sources": [5]
    },
    {
      "en": "This increased eye exploration was consistent and lasted longer once the eyes were reached.",
      "es": "Esta mayor exploración de los ojos fue consistente y duró más una vez que se alcanzaron los ojos.",
      "sources": [5]
    },
    {
      "en": "The study links oxytocin neuron activity to eye-focused social attention in primates for the first time.",
      "es": "El estudio vincula la actividad de las neuronas de oxitocina con la atención social enfocada en los ojos en primates por primera vez.",
      "sources": [7]
    }
  ]
}

{
  "sentences": [
    {
      "en": "The hat and spectre tiles cover the plane only in non-repeating patterns, and no cellular automaton behavior on them had been seen before.",
      "es": "Los azulejos hat y spectre cubren el plano solo en patrones no repetitivos, y antes no se había observado ningún comportamiento de autómata celular sobre ellos.",
      "sources": [0]
    },
    {
      "en": "Researchers used finite-state transducers to generate tile patches that can be exactly recreated from small records.",
      "es": "Los investigadores usaron transductores de estado finito para generar parches de azulejos que se pueden recrear exactamente a partir de registros pequeños.",
      "sources": [1]
    },
    {
      "en": "Initial searches under simple rules found no gliders, only patterns that eventually die out.",
      "es": "Las búsquedas iniciales con reglas simples no encontraron deslizadores, solo patrones que finalmente desaparecían.",
      "sources": [2]
    },
    {
      "en": "By expanding rules to include vertex neighborhoods and visible non-quiescent states, evolutionary search found gliders that travel one million rings at constant speed.",
      "es": "Al ampliar las reglas para incluir vecindarios de vértices y estados no en reposo visibles, la búsqueda evolutiva encontró deslizadores que viajan un millón de anillos a velocidad constante.",
      "sources": [3, 4]
    },
    {
      "en": "All glider paths align precisely to six fixed directions, matching the tiling's fastest graph axes.",
      "es": "Todas las trayectorias de los deslizadores se alinean exactamente con seis direcciones fijas, coincidiendo con los ejes más rápidos del gráfico del azulejo.",
      "sources": [5]
    },
    {
      "en": "Both rule extensions—vertex neighborhoods and visible states—are needed for gliders to appear.",
      "es": "Ambas extensiones de reglas—vecindarios de vértices y estados visibles—son necesarias para que aparezcan los deslizadores.",
      "sources": [6]
    },
    {
      "en": "Every result can be replayed exactly in an interactive essay provided with the study.",
      "es": "Cada resultado se puede reproducir exactamente en un ensayo interactivo proporcionado con el estudio.",
      "sources": [7]
    }
  ]
}

{
  "sentences": [
    {
      "en": "Researchers analyzed nearly 7,500 applications to a U.S. public policy master's program between 2020 and 2025.",
      "es": "Los investigadores analizaron casi 7.500 solicitudes a un programa de maestría en política pública pública de Estados Unidos entre 2020 y 2025.",
      "sources": [1]
    },
    {
      "en": "In 2025, most applicants submitted at least one essay mainly written by AI, even though it was forbidden.",
      "es": "En 2025, la mayoría de los solicitantes presentaron al menos un ensayo principalmente escrito por IA, aunque estaba prohibido.",
      "sources": [2]
    },
    {
      "en": "AI tools improved the writing quality of essays after ChatGPT became available in November 2022.",
      "es": "Las herramientas de IA mejoraron la calidad de la escritura de los ensayos después de que ChatGPT se volvió disponible en noviembre de 2022.",
      "sources": [3]
    },
    {
      "en": "Applicants who used AI to write essays were admitted less often than similar applicants who did not use AI.",
      "es": "Los solicitantes que usaron IA para escribir ensayos fueron admitidos con menos frecuencia que solicitantes similares que no usaron IA.",
      "sources": [4]
    },
    {
      "en": "Admissions officers often recognized AI-written essays and rated them lower than essays they thought were written by humans.",
      "es": "Los oficiales de admisión a menudo reconocieron ensayos escritos por IA y los calificaron más bajo que ensayos que creyeron escritos por humanos.",
      "sources": [5]
    }
  ]
}

{
  "sentences": [
    {
      "en": "Researchers used the VLBA to image two radio cores separated by 0.38 parsec in the central galaxy of the NGC 5044 group.",
      "es": "Los investigadores usaron el VLBA para imaginar dos núcleos de radio separados por 0.38 parsec en la galaxia central del grupo NGC 5044.",
      "sources": [4, 6]
    },
    {
      "en": "These cores are compact, have flat radio spectra, and vary in brightness, confirming them as binary active galactic nuclei.",
      "es": "Estos núcleos son compactos, tienen espectros de radio planos y varían en brillo, confirmando que son núcleos de galaxias activas binarios.",
      "sources": [6]
    },
    {
      "en": "This is the closest directly imaged binary AGN, separated by ten times less distance than the previous record.",
      "es": "Este es el AGN binario directamente imagenado más cercano, separado por diez veces menos distancia que el récord anterior.",
      "sources": [6]
    },
    {
      "en": "The older outbursts in the galaxy may have been caused by jets from the secondary core, without changing the main jet's direction.",
      "es": "Las erupciones antiguas en la galaxia podrían haber sido causadas por chorros del núcleo secundario, sin cambiar la dirección del chorro principal.",
      "sources": [5, 7]
    },
    {
      "en": "Massive elliptical galaxies at the centers of clusters may be good places to find more binary SMBHs.",
      "es": "Las galaxias elípticas masivas en los centros de cúmulos podrían ser buenos lugares para encontrar más SMBH binarios.",
      "sources": [8]
    }
  ]
}

{
  "sentences": [
    {
      "en": "NAVIR is an end-to-end audio-visual speech recognition system designed to run on the BrainChip Akida neuromorphic processor.",
      "es": "NAVIR es un sistema de reconocimiento de habla audiovisual de extremo a extremo diseñado para ejecutarse en el procesador neuromórfico BrainChip Akida.",
      "sources": [2]
    },
    {
      "en": "It uses separate modules for visual, temporal, and audio encoding, fused by a lightweight predictor and decoded with constrained beam search.",
      "es": "Utiliza módulos separados para codificar lo visual, lo temporal y lo auditivo, fusionados por un predictor ligero y decodificados con búsqueda con restricciones.",
      "sources": [3]
    },
    {
      "en": "The model was trained with noise-augmented audio and fine-tuned using quantization-aware training.",
      "es": "El modelo se entrenó con audio aumentado con ruido y se refinó usando entrenamiento consciente de cuantización.",
      "sources": [4]
    },
    {
      "en": "On the GRID benchmark, it achieved 14.0% word error rate under noise on unseen speakers and 3.3% on overlapped speakers, outperforming audio-only baselines.",
      "es": "En el benchmark GRID, logró una tasa de error de palabras del 14.0% con ruido en hablantes no vistos y del 3.3% en hablantes superpuestos, superando a los modelos solo auditivos.",
      "sources": [5]
    },
    {
      "en": "It uses 5 times less energy per inference than a Raspberry Pi CPU and over 100 times less than a laptop GPU, while processing 14.5 inferences per second.",
      "es": "Usa cinco veces menos energía por inferencia que una CPU de Raspberry Pi y más de cien veces menos que una GPU de laptop, mientras procesa 14.5 inferencias por segundo.",
      "sources": [7]
    }
  ]
}

{
  "sentences": [
    {
      "en": "Researchers created a material that can sense temperature or pressure by changing the balance of dopants in it.",
      "es": "Los investigadores crearon un material que puede detectar temperatura o presión al ajustar el equilibrio de dopantes en él.",
      "sources": [1]
    },
    {
      "en": "Different parts of the material emit light in ways that respond uniquely to temperature and pressure changes.",
      "es": "Diferentes partes del material emiten luz de formas que responden de manera única a los cambios de temperatura y presión.",
      "sources": [2]
    },
    {
      "en": "They used RGB camera images and multiple linear regression to turn color changes into precise temperature and pressure measurements.",
      "es": "Utilizaron imágenes de cámaras RGB y regresión lineal múltiple para convertir cambios de color en mediciones precisas de temperatura y presión.",
      "sources": [3]
    },
    {
      "en": "This method improved thermal sensitivity from about 1% per K to 8.8% per K and pressure sensitivity from 169% per GPa to nearly 721% per GPa.",
      "es": "Este método mejoró la sensibilidad térmica de aproximadamente 1% por K a 8.8% por K y la sensibilidad a la presión de 169% por GPa a casi 721% por GPa.",
      "sources": [4]
    },
    {
      "en": "This is the first time multiple linear regression with RGB imaging has been used to measure pressure from luminescent signals.",
      "es": "Esta es la primera vez que se usa regresión lineal múltiple con imágenes RGB para medir presión a partir de señales luminiscentes.",
      "sources": [5]
    }
  ]
}

{
  "sentences": [
    {
      "en": "Open-source text-to-image models can be intentionally designed for harmful uses, called Monets.",
      "es": "Los modelos de texto a imagen de código abierto pueden diseñarse intencionalmente para usos dañinos, llamados Monets.",
      "sources": [0]
    },
    {
